package com.hireflow.api.auth;
import jakarta.servlet.*;import jakarta.servlet.http.*;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.web.filter.OncePerRequestFilter;import java.io.IOException;import java.util.List;
public class JwtAuthFilter extends OncePerRequestFilter{private final JwtService jwt=new JwtService();protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException{String h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer ")){try{String t=h.substring(7);String e=jwt.email(t),role=jwt.role(t);SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(e,null,List.of(new SimpleGrantedAuthority("ROLE_"+role))));}catch(Exception ignored){}}c.doFilter(r,s);}}